def answers():
    rows = [("A", 3, 2, 0), ("B", 1, 1, 1), ("C", 2, 4, 0)]
    band = {c: both for c, r, w, both in rows}
    bor = {c: r + w + both for c, r, w, both in rows}
    out = []
    for c, r, w, both in rows:
        out += [band[c], bor[c]]
    return out + [max(band, key=band.get), max(bor, key=bor.get)]

