def answers():
    def f(x):
        x = float(x)
        return int(x) if x == int(x) else round(x, 2)
    import pandas as pd
    df = pd.DataFrame({"rain_mm": [0.0, None, 4.0, None, 2.5, 0.0], "wind_speed": [3.1, 2.5, None, 1.8, 4.2, 2.2]})
    out = []
    for sub in [["wind_speed"], ["rain_mm", "wind_speed"]]:
        d = df.dropna(subset=sub).copy()
        d["rain_mm"] = d["rain_mm"].fillna(0)
        r = d["rain_mm"] > 0
        out += [len(d), int(r.sum()), f(r.mean() * 100)]
    return out
